import{_ as a,C as i,o as r,c as o,E as n,a2 as s}from"./chunks/framework.BOeh4kYD.js";const b=JSON.parse('{"title":"定位到阶段，不等于找到根因","description":"","frontmatter":{"title":"定位到阶段，不等于找到根因","date":"2026-09-14","column":"open-source-engineering","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"独立评估者需要哪些执行轨迹证据，才能区分可信执行与不安全成功；阶段级归因又为什么不能直接等同于根因、授权或生产安全证明？","summary":"Trace（执行轨迹）能揭示终态成功背后的规划、记忆、工具与安全问题，并把可见异常定位到生命周期阶段；但 Attribution（归因）仍是评估判断，不能自动证明根因、授权或生产安全。","sources":["research/analysis/Q-20260914-03-trace-attribution-evidence-boundary.md"],"item_id":"Q-20260914-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-14-stage-attribution-not-root-cause-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-09-14-stage-attribution-not-root-cause.md","filePath":"zh/engineering/2026-09-14-stage-attribution-not-root-cause.md","lastUpdated":1789388081000}'),l={name:"zh/engineering/2026-09-14-stage-attribution-not-root-cause.md"};function p(c,e,u,d,h,g){const t=i("ArticleCover");return r(),o("div",null,[n(t,{image:"/assets/covers/daily-2026-09-14-stage-attribution-not-root-cause-cover.png",kicker:"开源工程 · 每日研究",title:"定位到阶段，不等于找到根因",summary:"Trace（执行轨迹）能揭示终态成功背后的规划、记忆、工具与安全问题，并把可见异常定位到生命周期阶段；但 Attribution（归因）仍是评估判断，不能自动证明根因、授权或生产安全。",version:"Q-20260914-03",status:"Daily Runtime V5 · 2026-09-14",languageHref:"/en/engineering/2026-09-14-stage-attribution-not-root-cause",languageLabel:"English"}),e[0]||(e[0]=s('<h1 id="定位到阶段-不等于找到根因" tabindex="-1">定位到阶段，不等于找到根因 <a class="header-anchor" href="#定位到阶段-不等于找到根因" aria-label="Permalink to &quot;定位到阶段，不等于找到根因&quot;">​</a></h1><p>两个 Agent（智能体）都完成了任务。一个遵循既定计划和工具策略；另一个执行了不安全指令，越过预期控制边界，却碰巧交付同样的文件。</p><p>若评估只看终态，两次运行同样成功。若读取 Trace（执行轨迹），差异才出现。但看到差异后还要保持克制：<strong>阶段级 Attribution（归因）可以指出异常在哪里显现，却不能仅凭更细的标签证明根因、当前授权或生产安全。</strong></p><h2 id="同样完成-可以完全不同" tabindex="-1">同样完成，可以完全不同 <a class="header-anchor" href="#同样完成-可以完全不同" aria-label="Permalink to &quot;同样完成，可以完全不同&quot;">​</a></h2><p>同日研究对象分析了 AgentAudit（智能体轨迹审计框架）的一手研究。该框架在运行结束后检查已记录轨迹，沿十个生命周期维度评分：指令完整性、规划、记忆、工具选择、工具调用、工具正确性、对齐、工具忠实性、安全与执行完整性。</p><p>研究覆盖五个模型和九类能力或对抗任务。报告结果显示，终态表现相似的模型仍可能在信任分类上明显不同；部分运行并非简单失败，而是 Unsafe Compliance（不安全服从）——任务完成了，但完成方式不值得接受。</p><p>这说明 <code>Completed</code>（已完成）只是一项结果事实。它不包含过程是否遵守策略、工具是否被正确选择、授权是否存在、记忆是否污染、执行是否忠实等信息。</p><h2 id="轨迹把结果拆回过程" tabindex="-1">轨迹把结果拆回过程 <a class="header-anchor" href="#轨迹把结果拆回过程" aria-label="Permalink to &quot;轨迹把结果拆回过程&quot;">​</a></h2><p>轨迹改变了证据单位。评估者不再只问“有没有结果”，而是读取 Agent 计划了什么、记住了什么、选择了哪个工具、传入了什么、得到了什么，以及接下来如何行动。</p><p>结构化生命周期有两个直接价值。第一，它能把“成功但不安全”从普通成功中分离。第二，它能把第一处可见异常关联到某个阶段，使修复从模糊的“模型不可靠”缩小为可检查问题：计划违反约束，记忆过期，工具选择错误，调用参数越界，或结果被错误解释。</p><p>但轨迹只能评价被记录的事实。若授权变化、外部效果或上游记忆来源没有进入轨迹，评估者无法从缺失数据恢复真相。更聪明的 Judge（裁判模型）也不能判断从未看到的证据。</p><h2 id="三个证据层不能互相替代" tabindex="-1">三个证据层不能互相替代 <a class="header-anchor" href="#三个证据层不能互相替代" aria-label="Permalink to &quot;三个证据层不能互相替代&quot;">​</a></h2><p>可审计系统至少要保存三个相互引用、但不能互相改写的层。</p><p><strong>观察事件层</strong>记录发生了什么：事件身份、时间、Actor（行动主体）、模型、工具、目标、请求与结果摘要、当时展示的授权证据，以及外部效果回执。这些是被审计的事实。</p><p><strong>评估判断层</strong>记录怎样解释：评估者身份、模型与版本、提示词、读取的轨迹区间、各维度分类、置信度、校准样例与不同评估者之间的分歧。</p><p><strong>因果与责任层</strong>记录为什么以及谁负责：明确标为假设或经评审结论，列出支持与反对证据、缺失变量、替代原因，以及需要时的人类或独立审查者。</p><p>AgentAudit 直接加强前两层。第三层通常需要额外证据。规划错误可能源于更早的记忆污染；越权工具调用可能因为当前授权事实根本没有提供给 Agent；第一处可见异常不一定是根因。</p><h2 id="单一裁判的相关偏差" tabindex="-1">单一裁判的相关偏差 <a class="header-anchor" href="#单一裁判的相关偏差" aria-label="Permalink to &quot;单一裁判的相关偏差&quot;">​</a></h2><p>研究明确保留一个重要限制：所有轨迹都由一个固定 Judge 模型评分，而该模型也在被评估模型之中。这会产生相关的解释与校准风险。</p><p>粒度更细并不自动更独立。一个 Judge 可以稳定地在十个维度上重复同一种偏差；多个 Judge 也可能共享训练数据、提示框架或盲点。若系统只输出最终信任分数，复杂评估反而可能制造比二元终态更有说服力的假确定性。</p><p>更可靠的做法是保存评估者身份与版本，使用已知正例和负例测量误报、漏报，并让分歧保持可见。Deterministic（确定性）规则可以锚定部分事实，例如调用参数是否超出白名单；语义上的不忠实或不安全服从仍可能需要模型或人工判断。</p><h2 id="可审计运行时应保存什么" tabindex="-1">可审计运行时应保存什么 <a class="header-anchor" href="#可审计运行时应保存什么" aria-label="Permalink to &quot;可审计运行时应保存什么&quot;">​</a></h2><p>一份最小但有用的轨迹不需要记录无限上下文，却必须保留会改变判断的身份：</p><ul><li>计划版本与任务约束；</li><li>关键记忆的读取与写入来源；</li><li>工具选择、请求参数与调用者；</li><li>工具响应和外部效果回执；</li><li>动作时读取的授权或策略版本；</li><li>重试、补偿、交接和终态事件；</li><li>评估者读取的确切事件范围；</li><li>评估提示词、模型版本、分类与置信度；</li><li>任何删减、脱敏或缺失字段的声明。</li></ul><p>模型生成的解释不能与工具回执混为一体。前者是解释，后者是外部事实。评估者可以引用事实，但不能把自己的标签写回成原始事件。</p><p>隐私与成本是现实约束。系统可按风险选择字段和保留期限，但脱敏后仍要保存足以理解“谁评价了什么”的稳定身份，否则审计只剩没有对象的结论。</p><h2 id="归因应触发调查-不应直接授权" tabindex="-1">归因应触发调查，不应直接授权 <a class="header-anchor" href="#归因应触发调查-不应直接授权" aria-label="Permalink to &quot;归因应触发调查，不应直接授权&quot;">​</a></h2><p>阶段归因最有价值的用途是缩小调查范围。若异常首次出现在工具选择阶段，可以检查候选工具、策略与上下文；若出现在记忆阶段，可以追查写入来源与新鲜度。</p><p>它不应自动分配组织责任，也不应授予下一次执行权。高信任分数不是当前 Business Authorization（业务授权）；低分也未必证明某个模型是根因。归因可以触发人工复核、补证或有界修复，但生命周期变更仍需自己的权威证据。</p><p>因此，终态报告应同时展示结果与过程质量：任务是否完成，执行是否忠实，安全约束是否满足，哪些维度未知，评估者之间是否一致。只有这样，“完成”才不会吞掉“怎样完成”。</p><h2 id="边界与未决问题" tabindex="-1">边界与未决问题 <a class="header-anchor" href="#边界与未决问题" aria-label="Permalink to &quot;边界与未决问题&quot;">​</a></h2><p>当前研究样本相对有限，也没有给出生产环境的误报率、漏报率或稳健的评估者间一致性。十个维度提供了有用结构，但不保证覆盖所有长期运行故障。</p><p>有界结论是：<strong>可信评估需要轨迹级可观察性和阶段归因，但归因必须保持评估判断身份。观察事件、评估结论与因果责任是三种不同证据；任何一项都不应凭借更细粒度取代另外两项。</strong></p><p>仍需回答的问题包括：哪些字段必须是不可变事实；怎样构建域内校准集；多个 Judge 分歧如何处理；何种错误率允许自动修复；何时必须由人类确认因果或责任；怎样在审计价值与敏感数据保护之间取平衡。</p><p><strong>证据与来源：</strong></p><ul><li><a href="https://arxiv.org/abs/2609.09875" target="_blank" rel="noreferrer">AgentAudit：轨迹级智能体生命周期评估</a>，一手研究，2026。</li></ul>',36))])}const _=a(l,[["render",p]]);export{b as __pageData,_ as default};
